alter table public.apex_payment_methods add column if not exists wallet_topup_enabled boolean not null default false; alter table public.apex_payment_methods add column if not exists gateway_provider text; comment on column public.apex_payment_methods.wallet_topup_enabled is 'Whether this payment method may be offered for customer wallet top-ups'; comment on column public.apex_payment_methods.gateway_provider is 'Non-secret provider identifier; credentials must be stored as Supabase Edge Function secrets';